import "./App.css";
import React, { useState, useEffect, useRef } from "react";
import logoImg from "./assets/logo.png";   // ← 이 줄 추가

/* ---------------------------------------------------------
   한끼잇다 (Hankki-Itda) — 공모전 화면 기준
   구조(App.js)와 스타일(App.css)을 분리한 버전.
   지도, 사진 영역은 전부 빈 placeholder 박스로만 처리
   (지도 API 연동 / 이미지 업로드 로직은 추후 별도 작업)
--------------------------------------------------------- */

/* ---------------- 공용 부품 ---------------- */

function Logo({ size = 22 }) {
  return (
    <div className="logo">
      <img src={logoImg} alt="한끼잇다 로고" className="logo__icon" style={{ height: size + 10 }} />
      <span className="logo__text" style={{ fontSize: size }}>
        한끼<span className="logo__text--green">잇다</span>
      </span>
    </div>
  );
}

/*------------------------------------------------------------------------*/

function Placeholder({ src, alt = "이미지", rounded = 12 }) {
  return (
    <div className="placeholder" style={{ borderRadius: rounded }}>
      {src && <img src={"Temp_main"} alt={alt} className="placeholder-img" />}
    </div>
  );
}



/* 프로필 아바타 자리 (헤더 우측 상단) */
function AvatarPlaceholder() {
  return <div className="avatar-placeholder" />;
}

function Header({ onNavigate, active }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    function onClick(e) {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false);
    }
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, []);

  const items = [
    { key: "list", label: "도시락 조회", icon: "🔍" },
    { key: "register", label: "식품 등록", icon: "📋" },
    { key: "mypage", label: "마이페이지", icon: "👤" },
  ];

  return (
    <div className="header">
      <div className="header__logo-link" onClick={() => onNavigate("home")}>
        <Logo />
      </div>

      <div className="header__right">
        <AvatarPlaceholder />
        <div className="header__menu" ref={ref}>
          <button className="header__menu-btn" onClick={() => setOpen((v) => !v)} aria-label="메뉴 열기">
            <span className="header__menu-bar" />
            <span className="header__menu-bar" />
            <span className="header__menu-bar" />
          </button>
          {open && (
            <div className="header__dropdown">
              {items.map((it) => (
                <div
                  key={it.key}
                  className={
                    "header__dropdown-item" + (active === it.key ? " header__dropdown-item--active" : "")
                  }
                  onClick={() => {
                    setOpen(false);
                    onNavigate(it.key);
                  }}
                >
                  <span className="header__dropdown-icon">{it.icon}</span>
                  {it.label}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function SearchBar({ value, onChange }) {
  return (
    <div className="search-bar">
      <div className="search-bar__box">
        <span className="search-bar__icon">⌕</span>
        <input
          className="search-bar__input"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder="지역, 제공처명을 검색하세요"
        />
      </div>
    </div>
  );
}

/* ---------------- 데이터 (임시 목데이터) ---------------- */

const PROVIDER = {
  name: "스타벅스 코엑스몰점",
  hours: "13:00 - 13:30",
  address: "서울특별시 마포구 월드컵로 212",
  phone: "02-3153-8114",
  remain: 12,
  items: ["소불고기", "배추김치", "시금치", "잡곡밥", "된장찌개"],
  allergy: "복숭아",
};

/* ---------------- 화면들 ---------------- */

function LoginScreen({ onNavigate }) {
  return (
    <div className="login-screen">
      <Logo size={26} />

      <div style={{ width: "100%" }}>
        <Placeholder height={220} label="음식 이미지 자리" icon="🍱" rounded={20} />
        <p className="login-screen__caption">
          오늘 남은 한 끼,
          <br />
          소중한 마음이 되어 이어집니다.
        </p>
      </div>

      <div className="login-screen__actions">
        <button className="btn btn--kakao btn--full" onClick={() => onNavigate("home")}>
          💬 카카오 로그인
        </button>
        <p className="login-screen__footnote">소중한 마음이 모여 누군가의 하루를 든든하게 채웁니다.</p>
      </div>
    </div>
  );
}

function HomeScreen({ onNavigate, query, setQuery }) {
  return (
    <div className="home-screen">
      <Header onNavigate={onNavigate} active="home" />
      <SearchBar value={query} onChange={setQuery} />
      <div className="home-screen__map-wrap" onClick={() => onNavigate("list")}>
        <Placeholder height="100%" rounded={0} label="지도 영역 (지도 API 연동 예정)" icon="🗺️" />
      </div>
    </div>
  );
}

function ListScreen({ onNavigate, query, setQuery }) {
  return (
    <div className="list-screen">
      <Header onNavigate={onNavigate} active="list" />
      <SearchBar value={query} onChange={setQuery} />
      <div className="list-screen__map-wrap">
        <Placeholder height="100%" rounded={0} label="지도 영역 (지도 API 연동 예정)" icon="🗺️" />
        <div className="list-card">
          <div className="list-card__thumb">
            <Placeholder height={58} rounded={10} label="" icon="🏪" />
          </div>
          <div className="list-card__info">
            <div className="list-card__name">{PROVIDER.name}</div>
            <div className="list-card__meta">
              ⏱ {PROVIDER.hours} · 잔여수량 {PROVIDER.remain}개
            </div>
          </div>
          <button className="btn btn--primary btn--sm" onClick={() => onNavigate("apply")}>
            신청하기
          </button>
        </div>
      </div>
    </div>
  );
}

function ApplyScreen({ onNavigate }) {
  const [time, setTime] = useState("");
  const [agree, setAgree] = useState(false);
  const [toast, setToast] = useState("");

  return (
    <div className="apply-screen">
      <Header onNavigate={onNavigate} active="list" />
      <div className="apply-screen__body">
        {/* 제공처 카드 */}
        <div className="provider-card">
          <div className="provider-card__thumb">
            <Placeholder height={72} rounded={10} label="" icon="🏪" />
          </div>
          <div>
            <div className="provider-card__name">{PROVIDER.name}</div>
            <div className="provider-card__meta">⏱ {PROVIDER.hours}</div>
            <div className="provider-card__meta">📍 {PROVIDER.address}</div>
            <div className="provider-card__phone">☎ {PROVIDER.phone}</div>
          </div>
        </div>

        {/* 음식 목록 카드 */}
        <div className="food-card">
          <div className="food-card__thumb">
            <Placeholder height={84} rounded={10} label="" icon="🍽️" />
          </div>
          <div style={{ flex: 1 }}>
            <ul className="food-card__list">
              {PROVIDER.items.map((it) => (
                <li key={it}>{it}</li>
              ))}
            </ul>
            <div className="allergy-row">
              <span className="allergy-row__label">알러지 주의 식품</span>
              <span className="allergy-tag">{PROVIDER.allergy}</span>
            </div>
          </div>
        </div>

        <div className="field-label">수령 시간을 입력하세요.</div>
        <input
          className="text-input"
          value={time}
          onChange={(e) => setTime(e.target.value)}
          placeholder="예: 오후 1:30"
        />

        <label className="agree-row">
          <input
            className="agree-row__checkbox"
            type="checkbox"
            checked={agree}
            onChange={(e) => setAgree(e.target.checked)}
          />
          <span className="agree-row__text">
            알레르기 유발 식품 정보를 충분히 확인하였으며, 사전에 고지된 알레르기 정보와 관련하여 발생한 피해에
            대해서는 책임을 묻지 않겠습니다.
          </span>
        </label>
      </div>

      <div className="action-bar">
        <button className="btn btn--secondary btn--block" onClick={() => onNavigate("list")}>
          취소하기
        </button>
        <button
          className="btn btn--primary btn--block"
          disabled={!agree || !time}
          onClick={() => {
            setToast("신청이 완료되었습니다.");
            setTimeout(() => {
              setToast("");
              onNavigate("home");
            }, 1400);
          }}
        >
          신청하기
        </button>
      </div>

      {toast && <div className="toast">{toast}</div>}
    </div>
  );
}

function NumberGrid({ count = 8, values, setValues }) {
  return (
    <div className="number-grid">
      {Array.from({ length: count }, (_, i) => (
        <input
          key={i}
          className="number-grid__input"
          value={values[i] || ""}
          onChange={(e) => {
            const next = [...values];
            next[i] = e.target.value;
            setValues(next);
          }}
          placeholder="+"
        />
      ))}
    </div>
  );
}

